"""PokéIsaac playable landing: original-host click-load window, startup and identity."""
from pathlib import Path

from guide_images import decorate
from play_recommendations import recommendations, stylesheet
from site_analytics import write_html

ROOT = Path(__file__).resolve().parents[1]
ROUTE = '/poke-isaac/'
GAME = 'https://pokeisaac.com/'
LEGAL = GAME + 'legal-en.html'
AD = '<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script>'


def ext(url, label):
    return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label} ↗<span class="sr-only"> (external website, opens in a new tab)</span></a>'


def ref(i):
    return f'<sup class="ref"><a href="#source-{i}" aria-label="Source {i}">[{i}]</a></sup>'


def sources(items):
    lis = ''.join(f'<li id="source-{i}">{ext(u, l)} — {d}</li>' for i, (u, l, d) in enumerate(items, 1))
    return f'<section class="sources" id="sources"><h2>Sources &amp; verification</h2><p>By Megabonk.org · checked 5 November 2026. Independent, source-based startup guide with an original-host inspection. PokéIsaac is an unofficial fan game by SrBatai; Pokémon names and artwork belong to Nintendo, Creatures Inc., GAME FREAK and The Pokémon Company, and The Binding of Isaac is a work by Edmund McMillen and Nicalis, Inc. This guide is unaffiliated with any of them.</p><ol>{lis}</ol><a class="back" href="#guide">Back to page ↑</a></section>'


NAV = f'<a href="{ROUTE}#play">Play</a><a href="{ROUTE}#start">Start here</a><a href="{ROUTE}#which-game">Which game?</a><a href="{ROUTE}#more-games">More games</a>'


def shell(title, desc, body):
    return stylesheet(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><link rel="canonical" href="https://megabonk.org{ROUTE}"><meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="https://megabonk.org{ROUTE}"><meta property="og:image" content="https://megabonk.org/assets/poke-isaac/menu-1280.webp"><link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="/assets/poke-survivor/play.css"><link rel="stylesheet" href="/assets/poke-isaac/site.css">{AD}<script defer src="/assets/poke-isaac/play.js"></script></head><body class="pkisaac-page guide-layout ps-play-page"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="/"><span>Megabonk.org<small>Independent games &amp; guides</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{NAV}</nav><details class="mobile-nav"><summary>Menu</summary><nav class="mobile-links" aria-label="Mobile navigation">{NAV}</nav></details></div></header><main class="wrap" id="main">{body}</main><footer class="footer"><div class="wrap footer-grid"><div><strong>Find your next game.</strong><p>Independent editorial by Megabonk.org. The original project operates the game and its services.</p><a href="/#wiki-start">More games &amp; guides →</a></div><nav aria-label="Site information"><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy-policy#poke-isaac">Privacy</a></nav></div></footer></body></html>''')


def page():
    body = f'''<header class="pk-intro" id="guide" data-play-background><div><p class="eyebrow">Pokémon × Binding of Isaac · browser roguelike · unofficial guide</p><h1>PokéIsaac</h1><p>A free fan-made dungeon roguelike by SrBatai: carry a team of up to three Pokémon room by room, grab items and descend through seven chapters. Play the original below or open it in its own tab — guest play needs no account. {ref(1)}</p><p class="pk-version">Original client v1.1.1 (beta label shown in-game) · menu, mode select, short run and pause menus checked 5 November 2026. The official landing page is Spanish; the client ships about a dozen languages and auto-matched our browser to Simplified Chinese. {ref(1)}</p></div><figure class="pk-hero"><img src="/assets/poke-isaac/mode-1280.webp" srcset="/assets/poke-isaac/mode-800.webp 800w, /assets/poke-isaac/mode-1280.webp 1280w" sizes="(max-width:900px) calc(100vw - 36px), 440px" width="1440" height="900" alt="Original PokéIsaac mode select: Classic with 7 chapters highlighted between Quartz League badges and the 4-player Co-op card"><figcaption class="pk-heronote">Original mode select, 5 November 2026. Game art © SrBatai / respective owners; not a promotional banner.</figcaption></figure></header>
<section class="game-panel" id="game-panel" aria-label="PokéIsaac game window" data-mode="normal"><div class="game-screen" id="play"><div class="game-cover" id="game-cover"><img src="/assets/poke-isaac/menu-1280.webp" srcset="/assets/poke-isaac/menu-800.webp 800w, /assets/poke-isaac/menu-1280.webp 1280w" sizes="(max-width:900px) calc(100vw - 36px), 620px" width="1280" height="800" alt="" loading="lazy"><div class="cover-content"><h2>PokéIsaac</h2><p>Rooms, items and chapter bosses — the Isaac loop with Pokémon shots.</p><button class="play-button" id="game-launch" type="button">Play PokéIsaac →</button><p class="cover-note">Click to load the original at pokeisaac.com.<br>Guest play needs no account; offline runs are not saved.</p></div></div><iframe id="game-frame" title="PokéIsaac original game hosted by pokeisaac.com" data-src="{GAME}" allow="autoplay; fullscreen; gamepad" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" hidden></iframe></div><div class="game-meta"><div class="game-tools"><button id="game-expand" type="button" aria-pressed="false" disabled>Expand game</button><button id="game-minimize" type="button" aria-expanded="true" aria-controls="play" disabled>Hide game</button>{ext(GAME, 'pokeisaac.com · open original')}</div><p id="game-status" role="status" aria-live="polite">Click Play to connect. Hiding keeps the session connected; it does not pause the game.</p><p>Keep this host and browser profile for your progress. A frame and a separate tab may receive different storage treatment. <a href="/privacy-policy#poke-isaac">Game-window privacy</a>.</p><noscript><p>{ext(GAME, 'pokeisaac.com · play the original in its own tab')}</p></noscript></div></section>
<div class="game-dock" id="game-dock" hidden><span>PokéIsaac hidden</span><button id="game-restore" type="button">Return to game ↑</button></div>
{recommendations('poke-isaac')}
<div class="pk-hub" id="routes"><a href="#start">First run<span>Login window → team → mode</span></a><a href="#controls">Controls<span>Move, shoot, switch, pause</span></a><a href="#save">Saves &amp; accounts<span>What is stored where</span></a><a href="#which-game">Which game?<span>Same-name checks</span></a></div>
<article class="play-notes" data-play-background><nav class="play-jump" aria-label="On this page"><a href="#about">About</a><a href="#start">First run</a><a href="#controls">Controls</a><a href="#save">Saves &amp; accounts</a><a href="#which-game">Which game?</a><a href="#sources">Sources</a></nav>
<section id="about"><h2>A fan tribute with its own built-in wiki</h2><p>PokéIsaac re-plays The Binding of Isaac's room-and-items loop with Pokémon: your shot type follows your Pokémon's type, items stack per run, and each chapter ends in a boss before the next floor. The project's own notice describes it as free and non-profit — no ads, purchases or sponsors — and says it is played only on its website, not distributed in app stores. {ref(2)}</p><p>The author advertises 971 Pokémon and 350 items. The Classic mode we inspected lists <strong>7 chapters of 3 floors</strong>, with super bosses, Mewtwo and Armored Mewtwo at the end, then an endless mode; a separate Quartz League tracks badge progress, and a menu button opens the project's Discord. {ref(1)}{ref(2)}</p><p>You do not need a wiki to start: the game ships an in-game <strong>Wiki</strong> menu (items, enemies, bosses, types, rooms, mechanics — several hundred entries in the client's current language). Use it for in-game lookups; this page stays focused on getting in, starting well and not losing progress.</p></section>
<section id="start"><h2>From login window to your first room</h2><p>These steps follow the original v1.1.1 client inspected on 5 November 2026, played as a guest with a short offline run. This is a startup check — no full clear or build advice is claimed. {ref(1)}</p><ol><li>Click <strong>Play</strong> above and wait for the game's login window. For a look-around session choose <strong>Play offline</strong> (guest): the window says plainly that nothing is saved — runs and rewards included. Signing in with email, Google or Discord instead keeps progress in an account. {ref(1)}{ref(2)}</li><li>Language: the client auto-detected our browser's language. Change it any time under <strong>Settings → Game → Language</strong>; the original landing page is Spanish, so do not judge the game by its landing page alone. {ref(1)}</li><li>On the main menu, the pedestal shows your lead Pokémon (a free Pikachu on a fresh profile) with two <strong>Add</strong> slots beside it — a team of up to three that you can switch during a run. Open <strong>My team</strong> to manage it.</li><li>Choose <strong>Start game</strong> and pick a mode: <strong>Classic</strong> (7 chapters × 3 floors, then endless), <strong>Quartz League</strong> (badge progression) or <strong>Co-op</strong>, which asks for <strong>at least 4 players</strong> — it is not a two-friend mode. {ref(1)}</li><li>In a room, move with WASD or the arrow keys and shoot in the direction you face; the panel on the left lists your current damage, fire rate, speed, range and luck. Read the info card that opens on the first room — it shows your type matchup multipliers for the floor. {ref(1)}</li><li>To continue an account run later, pause with <strong>Esc</strong> and use <strong>Save &amp; quit</strong> before closing the tab; the same menu offers restart and end-run buttons, and end-run asks for a second confirmation. {ref(1)}</li></ol><p>Weekly notices (right now, a Mystery Room event) appear on the menu and pause screens. Treat advertised events as current until the date you check them. {ref(1)}</p></section>
<section id="controls"><h2>Controls the game teaches first</h2><div class="table-wrap" tabindex="0" role="region" aria-label="PokéIsaac controls summary"><table class="pk-identity"><thead><tr><th>Task</th><th>Input</th><th>Check before relying on it</th></tr></thead><tbody><tr><td>Move</td><td>WASD or arrow keys; gamepad and touch are advertised in settings</td><td>Settings → Controls lists current bindings</td></tr><tr><td>Attack</td><td>Shoot in the direction you face; type decides the shot</td><td>The left panel shows damage and fire rate per Pokémon</td></tr><tr><td>Switch team member</td><td>Team of three; the pause screen names the lead form</td><td>Partners share the run — read the in-game Wiki entry if unsure</td></tr><tr><td>Pause / save</td><td>Esc → Save &amp; quit (account runs)</td><td>Guest runs cannot be resumed or rewarded</td></tr><tr><td>Enlarge this window</td><td>Expand game above; Esc returns to the page</td><td>Hiding keeps the frame connected, it does not pause the game</td></tr></tbody></table></div><p>The game exposes keyboard, mouse and gamepad settings and a language selector; we inspected menus at desktop and phone widths but have not benchmarked a physical phone or controller. {ref(1)}</p></section>
<section id="save"><h2>What is saved where</h2><p>The project's own notice is explicit: <strong>guest play saves nothing</strong> — the login window repeats that runs and rewards are not saved offline, and an end screen notes that rewards (tokens, tickets, medals) require an account. With an account (email via Supabase, Google or Discord), progress lives in the account, not the browser, and a saved run can be continued from another device; the browser only keeps your session and preferences. {ref(2)}</p><p>Practical routine: same host, same browser profile, save before closing. The notice also covers co-op: direct connection is on by default and lets other players in your room see your IP address — you can turn it off under Options → Data — and relayed games run through the project's servers (Supabase in the EU, Railway relays, Cloudflare TURN as fallback). We have not tested account creation, co-op sessions or save transfers ourselves. {ref(2)}</p><p>If the framed window stalls, {ext(GAME, 'open the original in its own tab')} before troubleshooting anything else; do not clear site data as a first step, since it removes the stored session. An outage on the original site cannot be fixed from this page.</p></section>
<section id="which-game"><h2>Check the name before following a guide</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Identify similarly named games"><table class="pk-identity"><thead><tr><th>Name you saw</th><th>What it actually is</th><th>Route</th></tr></thead><tbody><tr><td>PokéIsaac / Poke Isaac</td><td>This fan roguelike at pokeisaac.com by SrBatai; v1.1.1 beta, browser only, with an in-game Wiki and Discord. The project states it is not distributed on app stores.</td><td><a href="#play">Original window above</a></td></tr><tr><td>"Pokémon Isaac / PokeIsaac" APK files</td><td>An Android package (package name com.hark.pokeisaaczh…) circulated on APK sites. Not the official distribution — the project says it is website-only. We do not link it.</td><td>Stick to {ext(GAME, 'pokeisaac.com')}</td></tr><tr><td>PokeBonk / PokéSurvivor</td><td>Separate Pokémon-themed survival games with their own controls, hosts and progress.</td><td><a href="/pokebonk/play/">PokeBonk window</a> · <a href="/poke-survivor/play/">PokéSurvivor window</a></td></tr><tr><td>PokéVersus</td><td>A different free 3v3 Pokémon browser battler by Fl3xix with clans and rankings.</td><td>{ext('https://pokeversus.com/', 'pokeversus.com')}</td></tr><tr><td>The Binding of Isaac</td><td>The original game by Edmund McMillen and Nicalis; PokéIsaac only borrows its style of play.</td><td>{ext('https://www.bindingofisaac.com/', 'bindingofisaac.com')}</td></tr></tbody></table></div><p>Shared names do not mean shared accounts, saves or rosters — progress does not move between any of these games. {ref(2)}</p></section>
{sources([
    (GAME, 'PokéIsaac · original game', 'Original client v1.1.1 (beta label): login window, language setting, main menu, mode select, a short guest run in Chapter 1 (Eterna Forest) and pause menus inspected 5 November 2026 in desktop Chrome; phone-width menu viewed at 390 px, not a physical-device test. SINGLE_SOURCE for in-game flows.'),
    (LEGAL, 'PokéIsaac · legal notice &amp; privacy (English)', 'Read 5 November 2026: free non-profit fan game by SrBatai, website-only distribution statement, account/guest saving rules, co-op direct-connection IP note and technical providers. Project statements, not save-recovery tests.'),
    ('https://x.com/SrBatai', 'SrBatai on X · developer', 'Developer account named by the project notice; announcement of 19 October 2026 quoted via a repost. Identity context only.'),
])}</article>'''
    return shell('PokéIsaac: Play Online &amp; First-Run Guide | Megabonk',
                 'Play the free Pokémon × Binding of Isaac browser roguelike in an original-host window, with first-run steps, save behaviour and same-name checks.',
                 body)


def build():
    f = ROOT / 'poke-isaac/index.html'
    f.parent.mkdir(exist_ok=True)
    write_html(f, decorate(ROUTE, page()), encoding='utf-8')
    f = ROOT / 'index.html'
    text = f.read_text(encoding='utf-8')
    if 'id="pokeisaac-game-entry"' not in text:
        text = text.replace('<div class="route-grid">', '<div class="route-grid"><a class="route-card" id="pokeisaac-game-entry" href="/poke-isaac/"><h3>PokéIsaac</h3><p>Free Pokémon × Binding of Isaac browser roguelike: play the original in a click-loaded window, take the first-run path and check same-name games.</p><span class="route-link">Play &amp; start guide →</span></a>', 1)
        write_html(f, text, encoding='utf-8')
    f = ROOT / 'privacy-policy.html'
    text = f.read_text(encoding='utf-8')
    if 'id="poke-isaac"' not in text:
        text = text.replace('</body>', '<h2 id="poke-isaac">PokéIsaac game window</h2><p>Updated 5 November 2026. Clicking Play loads the original game from pokeisaac.com, including its resources and services (the project names Supabase, Railway, Google and Cloudflare in its own notice). Login, guest play and any account choices happen inside that window and belong to the original project; hiding the window keeps the same frame connected and does not pause the game — close or leave the page to end the session. Framed and separate-tab storage can differ; we cannot read or recover game saves, and guest runs are not saved by the game itself. Ordinary page integrations inherit this site\'s existing AdSense and site-wide Umami services described above.</p></body>', 1)
        write_html(f, text, encoding='utf-8')
    print('Built PokéIsaac playable landing; patched root entry/privacy.')


if __name__ == '__main__':
    build()
